parameters.jsCode:
const stdout = $input.first().json.stdout || '';
const exitCode = $input.first().json.exitCode || 0;
// Pipeline prints a single JSON line at end
const lines = stdout.trim().split('\n').filter(l => l.startsWith('{'));
const lastJson = lines.length ? lines[lines.length - 1] : '{}';
let summary = {};
try {
  summary = JSON.parse(lastJson);
} catch (e) {
  summary = { error: 'JSON parse failed', raw: lastJson };
}
return [{ json: { ...summary, exit_code: exitCode, ran_at: new Date().toISOString() } }];

